import AppKit
import Foundation
import MapCore
import MapIO
import Testing

@testable import Arbor

/// Hosted F-IO tests for the **current MindNode format** (ADR-0035):
/// opening such a file lands as a NEW untitled Arbor document with
/// the right titles, hierarchy and order — and the import-failure
/// alert now shows the underlying reason instead of a bare
/// "Import failed".
///
/// The `.mindnode` file opened here is the repo's committed
/// *synthetic* fixture (`Fixtures/mindnode/synthetic-current.mindnode`,
/// generated by `scripts/generate_mindnode_fixture.swift`) — no
/// personal document is ever committed.
@MainActor
struct MindNodeImportTests {
    /// The outline as (title) lines, for readable assertions.
    private func outline(_ model: MapModel) -> [String] {
        var lines: [String] = []
        func walk(_ id: String) {
            guard let node = model.nodes[id] else { return }
            lines.append(node.title.text)
            for child in node.children {
                walk(child)
            }
        }
        for root in model.roots {
            walk(root)
        }
        return lines
    }

    /// The committed synthetic fixture, copied to a unique temp file —
    /// the open path must work from anywhere, never touch the bundle.
    private func fixtureURL() throws -> URL {
        let bundled = try #require(
            Bundle(for: BundleToken.self).url(
                forResource: "synthetic-current", withExtension: "mindnode"))
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("hosted-\(UUID().uuidString).mindnode")
        try FileManager.default.copyItem(at: bundled, to: url)
        return url
    }

    @Test func openingACurrentFormatMindNodeFileCreatesAnUntitledDocument() throws {
        let url = try fixtureURL()
        defer { try? FileManager.default.removeItem(at: url) }

        let document = try #require(
            try NSDocumentController.shared.makeDocument(
                withContentsOf: url, ofType: "com.mindnode.mindnode") as? MapDocument)

        // A NEW untitled Arbor document (SPEC §5.17): the source URL
        // is dropped, the type is native, the next save asks where.
        #expect(document.fileURL == nil)
        #expect(document.fileType == AppIdentity.documentUTI)
        #expect(document.importedUntitled)

        // Titles, hierarchy and child order survive the trip —
        // including the empty node and the "floating text" branch;
        // the detached empty node stays excluded, as in MindNode's
        // own outline.
        #expect(
            outline(document.model) == [
                "Golden Root",
                "First branch",
                "Child one",
                "",
                "Second branch",
                "Floating text",
            ])
        #expect(MapValidator.validate(document.model).isEmpty)

        // Saving the import writes a native package, never back over
        // the source.
        let saved = FileManager.default.temporaryDirectory
            .appendingPathComponent("imported-\(UUID().uuidString).arbor")
        defer { try? FileManager.default.removeItem(at: saved) }
        try document.write(to: saved, ofType: AppIdentity.documentUTI)
        let reopened = try ArborPackage.read(at: saved).model
        #expect(outline(reopened) == outline(document.model))
        #expect(
            FileManager.default.fileExists(atPath: url.path), "the source must survive")
    }

    @Test func importPanelPathCreatesTheSameUntitledDocument() throws {
        let url = try fixtureURL()
        defer { try? FileManager.default.removeItem(at: url) }

        let document = try DocumentImporter.openForeignDocument(at: url)
        #expect(document.fileURL == nil)
        #expect(outline(document.model).first == "Golden Root")
        #expect(document.model.nodes.count == 6)
    }

    // MARK: the error sheet's text (F-IO: the reason, not just "failed")

    @Test func theImportAlertNamesTheFileAndShowsTheUnderlyingReason() {
        let tooNew = DocumentIOError.unsupportedVersion(
            format: DocumentFormats.mindnode.displayName, found: "3",
            hint: "This MindNode file uses a format Arbor can't read yet. "
                + "Open it in MindNode and export it as OPML, then import the OPML instead.")
        let error = ImportContextError(
            url: URL(fileURLWithPath: "/tmp/My own thought 1.mindnode"), underlying: tooNew)
        let alert = DocumentImporter.makeImportErrorAlert(for: error)

        #expect(alert.messageText == "Import failed — My own thought 1.mindnode")
        #expect(alert.informativeText.contains("version 3"))
        #expect(alert.informativeText.contains("Arbor can't read yet"))
        #expect(alert.informativeText.contains("OPML"))
    }

    @Test func theImportAlertShowsTheMalformedReasonToo() {
        let error = ImportContextError(
            url: URL(fileURLWithPath: "/tmp/broken.mindnode"),
            underlying: DocumentIOError.malformed(
                format: DocumentFormats.mindnode.displayName,
                reason: "Contents.data is not decodable protobuf"))
        let alert = DocumentImporter.makeImportErrorAlert(for: error)
        #expect(alert.messageText == "Import failed — broken.mindnode")
        #expect(alert.informativeText.contains("not decodable protobuf"))
    }
}

/// `Bundle(for:)` anchor for locating the test bundle's resources.
private final class BundleToken {}
